SET SCHEMA "BSCL";

DROP VIEW "BSCL.APV.BD.Vistas::ConsultarContratosAnalitica";

CREATE VIEW "BSCL.APV.BD.Vistas::ConsultarContratosAnalitica" AS
SELECT 
		Contrato."IdContratoSAAPV"                                                                                                                                              AS "IdContratoSAAPV" 
         , Contrato."NombrePlan"                                                                                                                                                AS "NombrePlanAhorro"
         , TO_NVARCHAR(Contrato."FechaSuscripcion", 'DD-MM-YYYY')                                                                                                               AS "FechaSuscripcion"
         , Contrato."FolioContratoSAAPV"                                                                                                                                        AS "FolioContrato"
         , Contrato."DocumentoIdentidadCliente"                                                                                                                                 AS "DocumentoIdentidadCliente"
         , CASE WHEN Persona."Tipo" = 'J' THEN Persona."RazonSocial" ELSE Persona."Nombres" END                                                             					AS "NombreCliente"
         , Persona."ApellidoPaterno"                                                                                                                                            AS "ApellidoPaternoCliente"
         , Persona."ApellidoMaterno"                                                                                                                                            AS "ApellidoMaternoCliente"
         , Inversionista."IdPersonaEjecutivo"                                                                                                                                   AS "IdEmpleadoEjecutivo"
         , CASE WHEN PersonaEjecutivo."Tipo" = 'J' THEN PersonaEjecutivo."RazonSocial" 
   			ELSE PersonaEjecutivo."Nombres" || ' ' || PersonaEjecutivo."ApellidoPaterno" || ' ' || PersonaEjecutivo."ApellidoMaterno" END                      					AS "NombrePersonaEjecutivo"
         , TO_NVARCHAR(Persona."FechaNacimiento", 'DD-MM-YYYY')                                                                                                                 AS "FechaNacimientoCliente"
         , PaisNacimiento."NombrePais"                                                                                                                                          AS "Nacionalidad"
         , TipoEstadoCivil."Nombre"                                                                                                                                             AS "EstadoCivil"
         , MAP(Persona."Sexo",'M','MASCULINO','FEMENINO')                                                                                                                       AS "Genero"
         , Profesion."Nombre"                                                                                                                                                   AS "CargoPersona"
         , Inversionista."IdCategoriaInversionista"                                                                                                                             AS "CategoriaInversionista"
         , PerfilComercial."IdPerfilComercialBaseOrigen"                                                                                                                        AS "PerfilComercial"                                                                                                                                                            
         , Contrato."EmailCliente"                                                                                                                                              AS "EmailCliente"
         , Contrato."DocumentoIdentidadEmpleador"                                                                                                                               AS "DocumentoIdentidadEmpleador"
         , Contrato."NombreEncargado"                                                                                                                                           AS "NombreEncargado"
         , Contrato."EmailEncargado"                                                                                                                                            AS "EmailEncargado"
         , Contrato."TelefonoEncargado"                                                                                                                                         AS "TelefonoEncargado"              
         , MAP(Contrato."IdMedioRecaudacionTrabajador",1,'IPS-EX INP','AFP')                                                                                                    AS "MedioRecaudacion"
         , EntidadRecaudadora."Nombre"                                                                                                                                          AS "EntidadRecaudadora"
         , Contrato."CodigoPrevision"                                                                                                                                           AS "CodigoPrevision"
         , Contrato."Pensionado"                                                                                                                                                AS "Pensionado"
         , Contrato."Trabajador"                                                                                                                                                AS "Trabajador"
         , Contrato."FormaDePago"                                                                                                                                               AS "FormaDePago"
         , MAP(Contrato."FormaDePago",'DIRECTA',MAP(Contrato."IdMedioRecaudacionFormaPago",1,'DIRECTAMENTE AL TRABAJADOR',2,'A TRAVES DEL EMPLEADOR','PAC'),NULL)               AS "Recaudador"
         , MAP(Contrato."FormaDePago",'DIRECTA',MAP(Contrato."IdMedioRecaudacionFormaPago",3,Contrato."DiaDescuento",NULL),NULL)                                                AS "DiaDescuento"
         , MAP(Contrato."FormaDePago",'INDIRECTA',MAP(Contrato."IdMedioRecaudacionTrabajador",1,'IPS-EX INP','AFP'),NULL)                                                       AS "Recaudacion"
         , MAP(Contrato."FormaDePago",'INDIRECTA',EntidadRecaudadora."Nombre",NULL)                                                                                             AS "Institucion"
         , MAP(Contrato."FormaDePago",'INDIRECTA',Contrato."ComisionTransferencia",NULL)                                                                                        AS "ComisionTransferencia"
         , Contrato."NombreEntidadOrigen"                                                                                                                                       AS "NombreEntidadOrigen"
         , Contrato."RutEntidadOrigen"                                                                                                                                          AS "RutEntidadOrigen"
         , Contrato."TipoDeAhorro"                                                                                                                                              AS "TipoDeAhorro"
         , Contrato."FondoDeOrigen"                                                                                                                                             AS "FondoDeOrigen"
         , Contrato."TipoTraspaso"                                                                                                                                              AS "TipoTraspaso"
         , Contrato."MontoTraspaso"                                                                                                                                             AS "MontoTraspaso"
         , Contrato."UFTraspaso"                                                                                                                                                AS "UFTraspaso"
         , Contrato."PorcentajeTraspaso"                                                                                                                                        AS "PorcentajeTraspaso"
         , MAP(PortafolioContrato."IdPortafolio",NULL,NULL,Portafolio."IdPortafolio")                                                                                           AS "IdPortafolio"
         , MAP(PortafolioContrato."IdPortafolio",NULL,NULL,MatrizAgrupador."Producto")                                                                                          AS "Producto"
         , COALESCE(PortafolioContrato."MontoPesos",0)                                                                                                                          AS "MontoPesos"
         , COALESCE(PortafolioContrato."MontoUF",0)                                                                                                                             AS "MontoUF"
         , COALESCE(PortafolioContrato."PorcentajeRegimenImponible",0)                                                                                                          AS "Porcentaje"
         , MAP(PortafolioContrato."IdPortafolio",NULL,NULL,PortafolioContrato."Pago")                                                                                           AS "Pago"
         , MAP(PortafolioContrato."IdPortafolio",NULL,NULL,PortafolioContrato."PeriodoInicio")                                                                                  AS "PeriodoInicio"
         , MAP(PortafolioContrato."IdPortafolio",NULL,NULL,PortafolioContrato."PeriodoTermino")                                                                                 AS "PeriodoTermino"
         , MAP(PortafolioContrato."IdPortafolio",NULL,NULL,MatrizAgrupador."Codigo")                                                                                            AS "RegimenTributario"
         , Portafolio."IdMatrizAgrupadorAPV"                                                                                                                                    AS "IdMatrizAgrupadorAPV"
         , MatrizAgrupador."CodigoAgrupador"                                                                                                                                    AS "CodigoAgrupador"
         , Portafolio."Proposito"                                                                                                                                               AS "Proposito"
         , Contrato."CodigoTipoSolicitud"                                                                                                                                       AS "CodigoTipoSolicitud"
         , Traspaso."TipoMovimiento"                                                                                                                                            AS "TipoMovimiento"
         , DetalleOrigenTraspaso."IdDetalleOrigenTraspaso"                                                                                                                      AS "IdDetalleOrigenTraspaso"
         , DetalleOrigenTraspaso."DocumentoEntidad"                                                                                                                             AS "DocumentoIdentidadEntidadDestino"
         , DetalleOrigenTraspaso."NombreEntidad"                                                                                                                                AS "NombreEntidadDestino"
         , DetalleOrigenTraspaso."Fondo"    																																	AS "IdSerieFondo"
         , DetalleOrigenTraspaso."MontoTraspaso"                                                                                                                      			AS "MontoDetalleTraspaso"
         , SerieDeFondoOrigen."IdFondo"                                                                                                                                         AS "IdFondo"
         , FondoDestino."NombreFondo"                                                                                                                                    		AS "FondoDestino"
         , DetalleOrigenTraspaso."CodigoRegimenTributario"                                                                                                                      AS "RegimenTributarioDestino"
         , Contrato."IdEstado"                                                                                                                                                  AS "IdEstado"
         , EstadoContrato."Nombre"                                                                                                                                              AS "EstadoContrato"
         , COALESCE(MatrizAgrupador."EsADC",'N') AS "EsADC"
         , Contrato."IdMedioRecaudacionFormaPago"
        FROM "BSCL.APV.BD::SCS.ContratoSAAPV" AS Contrato
        LEFT OUTER JOIN "BSCL.SocioNegocio.BD::PER.Persona" AS Persona ON Persona."IdPersona" = Contrato."IdPersona"
        LEFT OUTER JOIN "BSCL.Plataforma.BD::REG.TipoEstadoCivil" AS TipoEstadoCivil ON TipoEstadoCivil."IdTipoEstadoCivil" = Persona."EstadoCivil"
        LEFT OUTER JOIN "BSCL.Plataforma.BD::REG.Pais" AS PaisNacimiento ON PaisNacimiento."IdPais" = Persona."IdPaisNacionalidadPrincipal"
        LEFT OUTER JOIN "BSCL.SocioNegocio.BD::CLI.Cliente" AS Inversionista ON Inversionista."IdPersona" = Persona."IdPersona"
        LEFT OUTER JOIN "BSCL.SocioNegocio.BD::PER.Persona" AS PersonaEjecutivo ON Inversionista."IdPersonaEjecutivo" = PersonaEjecutivo."IdPersona"                    
        LEFT OUTER JOIN "BSCL.APV.BD::SCS.PortafolioContratoSAAPV" AS PortafolioContrato ON PortafolioContrato."IdContratoSAAPV" = Contrato."IdContratoSAAPV"
        LEFT OUTER JOIN "BSCL.Portafolio.BD::POR.Portafolio" AS Portafolio ON Portafolio."IdPortafolio" = PortafolioContrato."IdPortafolio" AND Portafolio."IdCliente" = Contrato."IdCliente" AND Portafolio."IdEstado" <> 'INA'
        LEFT OUTER JOIN "BSCL.APV.BD::SCS.EntidadRecaudadora" AS EntidadRecaudadora ON EntidadRecaudadora."Codigo" = Contrato."CodigoPrevision"
        LEFT OUTER JOIN "BSCL.Portafolio.BD.Vistas::ConsultarMatrizAgrupadorAnalitica" AS MatrizAgrupador ON MatrizAgrupador."IdMatrizAgrupadorAPV" = Portafolio."IdMatrizAgrupadorAPV"
        LEFT OUTER JOIN "BSCL.Portafolio.BD::POR.Portafolio" AS PerfilComercial ON PerfilComercial."IdPortafolio" = Portafolio."IdPortafolio" AND PerfilComercial."IdCliente" = Contrato."IdCliente" AND PerfilComercial."IdEstado" <> 'INA'
        LEFT OUTER JOIN "BSCL.Plataforma.BD::REG.Profesion" AS Profesion ON Profesion."IdProfesion" = Persona."IdProfesion"
        LEFT OUTER JOIN "BSCL.APV.BD::TRA.Traspaso" AS Traspaso ON Traspaso."IdContratoSAAPV" = Contrato."IdContratoSAAPV"
        LEFT OUTER JOIN "BSCL.APV.BD::TRA.DetalleOrigenTraspaso" DetalleOrigenTraspaso ON DetalleOrigenTraspaso."IdTraspaso" = Traspaso."IdTraspaso"
        LEFT OUTER JOIN "BSCL.FondoMutuo.BD::FMM.SerieDeFondo" AS SerieDeFondoOrigen ON SerieDeFondoOrigen."IdSerieFondo" = DetalleOrigenTraspaso."Fondo"
        LEFT OUTER JOIN "BSCL.FondoMutuo.BD::FMM.SerieDeFondo" AS SerieDeFondoDestino ON SerieDeFondoDestino."IdInstrumento" = DetalleOrigenTraspaso."IdInstrumento"
		LEFT OUTER JOIN "BSCL.FondoMutuo.BD::FMM.Fondo" AS FondoDestino ON FondoDestino."IdFondo" = SerieDeFondoDestino."IdFondo"
		LEFT OUTER JOIN "BSCL.Plataforma.BD::PLA.Estado" AS EstadoContrato ON EstadoContrato."IdEstado" = Contrato."IdEstado";

GRANT SELECT ON "BSCL.APV.BD.Vistas::ConsultarContratosAnalitica" TO BCS_DESARROLLADOR WITH GRANT OPTION;
